/* Desktop XR testing: ordinary mouse clicks or centre-pointer + Space/Enter. */
(()=>{
const T=AFRAME.THREE;
AFRAME.registerComponent('xr-easy-input',{
 init(){this.listeners=[];this.ndc=new T.Vector2();this.cursor={components:{raycaster:{getIntersection:el=>this.current?.el===el?this.current.intersection:null}}};this.reticle=new T.Mesh(new T.RingGeometry(.006,.009,24),new T.MeshBasicMaterial({color:'#87bd9b',transparent:true,opacity:.95,depthTest:false,depthWrite:false,side:T.DoubleSide}));this.reticle.renderOrder=27000;this.reticle.visible=false;this.el.object3D.add(this.reticle);this.gazeRing=new T.Mesh(new T.RingGeometry(.014,.019,48),new T.MeshBasicMaterial({color:'#78bda5',transparent:true,opacity:.9,depthTest:false,depthWrite:false,side:T.DoubleSide}));this.gazeRing.renderOrder=30000;this.gazeRing.visible=false;this.el.object3D.add(this.gazeRing);
  this.listen(window,'pointermove',e=>{if(!this.validPointer(e))return;this.updatePointer(e);if(this.drag){this.drag?.moveMouse(this.ray(true));e.preventDefault?.();e.stopImmediatePropagation?.()}},true);
  this.listen(window,'pointerdown',e=>{if(e.button!==0||!this.validPointer(e))return;if(window.globiquest.artPlay?.mouseDown(e))return;this.updatePointer(e);const ray=this.ray(true),hit=this.hit(ray);if(!hit)return;this.current=hit;const dragger=window.globiquest.panelDraggerFor?.(hit.el)||window.globiquest.navDragger,region=window.GlobiquestPanelInput?.region(hit);if((hit.el.id==='xrNavDragHandle'||hit.el.getAttribute?.('data-panel-grip')==='true'||region?.drag)&&dragger?.startMouse(ray,hit.el))this.drag=dragger;else{this.down=hit;this.emit(hit,'mousedown')}e.preventDefault?.();e.stopImmediatePropagation?.()},true);
  this.listen(window,'pointerup',e=>{if(!this.down&&!this.drag)return;if(this.validPointer(e))this.updatePointer(e);if(this.drag){this.drag?.end();this.drag=null}else{const down=this.down;this.current=this.validPointer(e)?this.hit(this.ray(true)):null;this.emit(down,'mouseup');if(this.current?.el===down.el)this.emit(down,'click');this.down=null}this.suppressClick=performance.now()+400;e.preventDefault?.();e.stopImmediatePropagation?.()},true);
  this.listen(window,'click',e=>{if(this.validPointer(e)&&performance.now()<(this.suppressClick||0))e.stopImmediatePropagation?.()},true);
  this.listen(window,'keydown',e=>{if(!this.el.is('vr-mode')||e.repeat||!['Space','Enter'].includes(e.code)||window.globiquest.travelEditing||/INPUT|TEXTAREA|SELECT/.test(e.target?.tagName||'')||e.target?.isContentEditable)return;e.preventDefault?.();this.pointerAt=0;const hit=this.hit(this.ray(false));if(!hit)return;this.current=hit;this.emit(hit,'mousedown');this.emit(hit,'mouseup');this.emit(hit,'click');e.preventDefault?.();e.stopImmediatePropagation?.()},true);
  this.listen(window,'blur',()=>this.cancel());this.listen(this.el,'exit-vr',()=>this.cancel());window.globiquest.easyXRInput=true;window.globiquest.xrPointerCamera=()=>this.pointerCamera();
 },
 listen(el,name,fn,capture=false){el?.addEventListener?.(name,fn,capture);this.listeners.push(()=>el?.removeEventListener?.(name,fn,capture))},
 validPointer(e){return this.el.is('vr-mode')&&e.target===this.el.canvas},
 updatePointer(e){const r=this.el.canvas.getBoundingClientRect();this.ndc.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);this.pointerAt=performance.now()},
 pointerCamera(){const base=this.el.camera,xr=this.el.renderer?.xr,immersive=this.el.is('vr-mode')&&xr?.getSession?.()&&xr.getCamera?.(base);if(!immersive)return base;const eyes=immersive.cameras||[],reference=eyes[0]||base,camera=this.viewCamera||(this.viewCamera=new T.PerspectiveCamera());camera.projectionMatrix.copy(reference.projectionMatrix);if(eyes.length>1){for(const index of [8,9])camera.projectionMatrix.elements[index]=eyes.reduce((sum,eye)=>sum+eye.projectionMatrix.elements[index],0)/eyes.length}camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();const position=new T.Vector3();if(eyes.length){for(const eye of eyes)position.add(new T.Vector3().setFromMatrixPosition(eye.matrixWorld));position.multiplyScalar(1/eyes.length)}else position.setFromMatrixPosition(immersive.matrixWorld);camera.matrixWorld.compose(position,new T.Quaternion().setFromRotationMatrix(immersive.matrixWorld),new T.Vector3(1,1,1));camera.matrixWorldInverse.copy(camera.matrixWorld).invert();return camera},
 ray(mouse){const caster=new T.Raycaster(),camera=this.pointerCamera();if(camera===this.el.camera)camera.updateWorldMatrix(true,false);caster.setFromCamera(mouse?this.ndc:new T.Vector2(),camera);return caster.ray},
 hit(ray){const caster=new T.Raycaster(ray.origin,ray.direction,.01,30);let closest=null;for(const el of this.el.querySelectorAll('.interactive')){let visible=true;for(let p=el.__panelOwner?.object3D;p;p=p.parent)if(!p.visible)visible=false;for(let o=el.object3D;o;o=o.parent)if(!o.visible)visible=false;if(!visible)continue;el.object3D.updateWorldMatrix(true,true);const intersection=caster.intersectObject(el.object3D,true)[0];if(intersection&&(window.GlobiquestPanelInput?.better?window.GlobiquestPanelInput.better({el,intersection},closest):!closest||intersection.distance<closest.intersection.distance))closest={el,intersection}}return closest},
 emit(hit,type){hit?.el.emit(type,{cursorEl:this.cursor,intersection:hit.intersection,inputSource:'easy-xr'},true)},
 cancel(){if(this.down)this.emit(this.down,'mouseup');if(this.drag)this.drag.end(true);this.down=null;this.drag=false;this.reticle.visible=false;this.gazeRing.visible=false;this.gaze=null},
 updateGaze(){const now=performance.now();this.gazeRing.visible=false;if(!this.el.is('vr-mode')||this.drag||window.globiquest.isPanelDragging?.()){this.gaze=null;return}const hit=this.hit(this.ray(false)),region=window.GlobiquestPanelInput?.region(hit);if(window.globiquest.artPlay?.airActive&&!/stop|finish|undo|clear|close/i.test(region?.label||'')){this.gaze=null;return}if(region?.dwell===false){this.gaze=null;return}if(!region?.action||region.drag||/delete|save|png/i.test(region.label||'')){if(this.gaze&&now-(this.gaze.lastSeen||0)>250)this.gaze=null;return}const owner=hit.el.closest?.('[id]')?.id||hit.el.parentElement?.id||'',key=owner+'|'+region.label;if(this.gaze?.latched&&this.gaze.point?.distanceTo(hit.intersection.point)<.08){this.gaze.lastSeen=now;return}if(this.gaze?.key!==key)this.gaze={key,since:now,lastSeen:now,latched:false};const gaze=this.gaze;gaze.lastSeen=now;const progress=Math.min(1,(now-gaze.since)/1200);this.gazeRing.position.copy(hit.intersection.point);this.gazeRing.lookAt(window.globiquest.xrHeadPose?.()?.position||this.el.camera.getWorldPosition(new T.Vector3()));this.gazeRing.scale.setScalar(Math.max(.6,hit.intersection.distance));this.gazeRing.geometry.setDrawRange(0,Math.floor(this.gazeRing.geometry.index.count*progress/3)*3);this.gazeRing.visible=!gaze.latched;if(progress>=1&&!gaze.latched){gaze.latched=true;gaze.point=hit.intersection.point.clone();window.GlobiquestPanelInput?.hover(hit);region.action()}},
 tick(){this.updateGaze();if(!this.el.is('vr-mode')){this.reticle.visible=false;return}const ray=this.ray(performance.now()-(this.pointerAt||-10000)<1500),hit=this.hit(ray);this.current=hit;window.GlobiquestPanelInput?.hover(hit);this.reticle.visible=!!hit;if(hit){this.reticle.position.copy(hit.intersection.point);this.reticle.lookAt(this.el.camera.getWorldPosition(new T.Vector3()));this.reticle.scale.setScalar(Math.max(.5,hit.intersection.distance))}},
 remove(){this.cancel();this.listeners.forEach(fn=>fn());this.reticle.removeFromParent();this.reticle.geometry.dispose();this.reticle.material.dispose();this.gazeRing.removeFromParent();this.gazeRing.geometry.dispose();this.gazeRing.material.dispose();delete window.globiquest.xrPointerCamera;delete window.globiquest.easyXRInput}
});
const setup=()=>scene.setAttribute('xr-easy-input','');if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});
})();
